import re

headers = ['Item Code', 'Item Name ', 'Price (USD)', 'Stock']

def clean_header(name):
    return re.sub(r'[^0-9a-z]+', '_', name.strip().lower()).strip('_')

print([clean_header(h) for h in headers])

